    pub fn new(id: usize, name: &str) -> Self {
        Self {
            id,
            name: name.to_string(),
            data: HashMap::new(),
            metrics: Vec::new(),
            flags: HashSet::new(),
            depth: 0,
            buf: Vec::new(),
            index: BTreeMap::new(),
        }
    }

