pub fn tdmerge_fn_1(map: &HashMap<String, String>, key: &str) -> Vec<String> {
    map.iter()
        .filter(|(k, _)| k.contains(key))
        .map(|(_, v)| v.clone())
        .collect()
}

pub fn tdmerge_fn_2(vals: &[f64]) -> (f64, f64, f64) {
    if vals.is_empty() {
        return (0.0, 0.0, 0.0);
    }
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    (min, max, avg)
}

pub fn tdmerge_fn_3(a: &HashSet<String>, b: &HashSet<String>) -> HashSet<String> {
    a.intersection(b).cloned().collect()
}

pub fn tdmerge_fn_4(input: &str, chunk: usize) -> Vec<String> {
    input
        .chars()
        .collect::<Vec<_>>()
        .chunks(chunk.max(1))
        .map(|c| c.iter().collect())
        .collect()
}

pub fn tdmerge_fn_5(tree: &BTreeMap<String, usize>, min: usize) -> BTreeMap<String, usize> {
    tree.iter()
        .filter(|(_, v)| **v >= min)
        .map(|(k, v)| (k.clone(), *v))
        .collect()
}

pub fn tdmerge_fn_6(data: &[u8], offset: usize) -> Option<u64> {
    if offset + 8 > data.len() {
        return None;
    }
    let bytes: [u8; 8] = data[offset..offset + 8].try_into().ok()?;
    Some(u64::from_le_bytes(bytes))
}

pub fn tdmerge_fn_7(queue: &VecDeque<String>, max: usize) -> Vec<String> {
    queue.iter().take(max).cloned().collect()
}

pub fn tdmerge_fn_8(items: &[&str], sep: &str) -> String {
    items
        .iter()
        .filter(|s| !s.is_empty())
        .copied()
        .collect::<Vec<_>>()
        .join(sep)
}

pub fn tdmerge_fn_9(map: &HashMap<String, String>, key: &str) -> Vec<String> {
    map.iter()
        .filter(|(k, _)| k.contains(key))
        .map(|(_, v)| v.clone())
        .collect()
}

pub fn tdmerge_fn_10(vals: &[f64]) -> (f64, f64, f64) {
    if vals.is_empty() {
        return (0.0, 0.0, 0.0);
    }
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    (min, max, avg)
}

pub fn tdmerge_fn_11(a: &HashSet<String>, b: &HashSet<String>) -> HashSet<String> {
    a.intersection(b).cloned().collect()
}

pub fn tdmerge_fn_12(input: &str, chunk: usize) -> Vec<String> {
    input
        .chars()
        .collect::<Vec<_>>()
        .chunks(chunk.max(1))
        .map(|c| c.iter().collect())
        .collect()
}

pub fn tdmerge_fn_13(tree: &BTreeMap<String, usize>, min: usize) -> BTreeMap<String, usize> {
    tree.iter()
        .filter(|(_, v)| **v >= min)
        .map(|(k, v)| (k.clone(), *v))
        .collect()
}

pub fn tdmerge_fn_14(data: &[u8], offset: usize) -> Option<u64> {
    if offset + 8 > data.len() {
        return None;
    }
    let bytes: [u8; 8] = data[offset..offset + 8].try_into().ok()?;
    Some(u64::from_le_bytes(bytes))
}

pub fn tdmerge_fn_15(queue: &VecDeque<String>, max: usize) -> Vec<String> {
    queue.iter().take(max).cloned().collect()
}

pub fn tdmerge_fn_16(items: &[&str], sep: &str) -> String {
    items
        .iter()
        .filter(|s| !s.is_empty())
        .copied()
        .collect::<Vec<_>>()
        .join(sep)
}

pub fn tdmerge_fn_17(map: &HashMap<String, String>, key: &str) -> Vec<String> {
    map.iter()
        .filter(|(k, _)| k.contains(key))
        .map(|(_, v)| v.clone())
        .collect()
}

pub fn tdmerge_fn_18(vals: &[f64]) -> (f64, f64, f64) {
    if vals.is_empty() {
        return (0.0, 0.0, 0.0);
    }
    let min = vals.iter().cloned().fold(f64::INFINITY, f64::min);
    let max = vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let avg = vals.iter().sum::<f64>() / vals.len() as f64;
    (min, max, avg)
}

