#[pyfunction]
pub fn rust_tdmerge_run(_py: Python<'_>, key: &str, val: &str) -> PyResult<bool> {
    let mut e = TDMergeCore1::new(0, key);
    e.data.insert(key.to_string(), val.to_string());
    Ok(e.data.contains_key(key))
}

